{
  "status": "SUPPORTED",
  "task_summary": "Relocate refreshment items and remote control from the foreground console to accessible surfaces within the seating area.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "source_console_surface",
        "entity_kind": "OBJECT",
        "function": "Storage surface for original items",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["wooden console table", "credenza", "sideboard"],
        "required_properties": []
      },
      {
        "id": "destination_surface",
        "entity_kind": "REGION",
        "function": "Support surface for relocated items",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["coffee table", "end table", "low table", "bench"],
        "required_properties": ["supports_horizontal_load"]
      },
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Group of drinkware and plates for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup with plate", "drinkware set", "bowl and fork"],
        "required_properties": ["holds_food_or_liquid"]
      },
      {
        "id": "entertainment_controller",
        "entity_kind": "OBJECT",
        "function": "Device to control media display",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["remote control", "media button", "device interface"],
        "required_properties": ["has_buttons_for_television"]
      }
    ],
    "functional_relations": [
      {
        "id": "rel_items_on_source",
        "subject_role": "refreshment_setting",
        "relation": "initially_rests_above",
        "object_role": "source_console_surface",
        "required": true
      },
      {
        "id": "rel_remote_on_source",
        "subject_role": "entertainment_controller",
        "relation": "initially_rests_above",
        "object_role": "source_console_surface",
        "required": true
      },
      {
        "id": "rel_destination_proximity",
        "subject_role": "destination_surface",
        "relation": "located_adjacent_to_seating_zone",
        "object_role": "living_room_floor",
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_move_refreshments",
        "operation": "transfer_refreshment_setting",
        "source_role": "refreshment_setting",
        "target_role": "destination_surface",
        "operation_count": 2,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "destination_surface"
      },
      {
        "id": "op_move_controller",
        "operation": "transfer_entertainment_controller",
        "source_role": "entertainment_controller",
        "target_role": "destination_surface",
        "operation_count": 1,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS",
        "anchor_role": "destination_surface"
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "source_console_surface": [
        {
          "label": "Foreground Console Table",
          "visual_description": "Large wooden cabinet console in foreground with remote, cups, and plates on top."
        }
      ],
      "destination_surface": [
        {
          "label": "Glass-top Coffee Table",
          "visual_description": "Central low table with light-colored glass top positioned between armchairs."
        },
        {
          "label": "Wooden Side Table",
          "visual_description": "Small square side table next to the right-facing armchair."
        }
      ],
      "refreshment_setting": [
        {
          "label": "Red Cup and White Plate",
          "visual_description": "Set of red mug and white plate visible on the source console."
        },
        {
          "label": "Second Red Cup and Plate",
          "visual_description": "Duplicate second set of red mug and white plate on source console."
        }
      ],
      "entertainment_controller": [
        {
          "label": "Black Remote Control",
          "visual_description": "Black rectangular remote control situated on the source console among dishes."
        }
      ]
    },
    "inspectable_regions": [],
    "inspection_order": []
  }
  ,
  "unsupported_reason": ""
}
